{"command":"cat > /tmp/pty_seq.py <<'PY'
import os, subprocess, time, fcntl, termios, struct, select, sys, signal, ast
# Usage: python pty_seq.py DUR ROWS COLS cmd... ; events from env EVENTS as Python list [(delay, bytes_hex_or_str),...]
if len(sys.argv) < 5:
    print('usage'); sys.exit(1)
dur=float(sys.argv[1]); rows=int(sys.argv[2]); cols=int(sys.argv[3]); cmd=sys.argv[4:]
master, slave = os.openpty()
fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
env=os.environ.copy(); env.setdefault('TERM','xterm-256color')
p=subprocess.Popen(cmd, stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
os.close(slave)
fcntl.fcntl(master, fcntl.F_SETFL, os.O_NONBLOCK)
events=[]
if os.environ.get('EVENTS'):
    # list of [delay, value]; value starts hex: or is string with escapes
    raw=ast.literal_eval(os.environ['EVENTS'])
    for delay,val in raw:
        if isinstance(val, bytes): b=val
        elif isinstance(val,str) and val.startswith('hex:'): b=bytes.fromhex(val[4:])
        elif isinstance(val,str): b=val.encode('utf-8').decode('unicode_escape').encode('latin1')
        else: b=bytes(val)
        events.append((float(delay),b))
events.sort(); idx=0; data=b''; start=time.time()
while time.time()-start < dur:
    now=time.time()-start
    while idx<len(events) and now>=events[idx][0]:
        try: os.write(master, events[idx][1])
        except OSError: pass
        idx+=1
    r,_,_=select.select([master],[],[],0.02)
    if r:
        try:
            chunk=os.read(master,8192)
            if not chunk: break
            data += chunk
        except OSError: break
    if p.poll() is not None:
        # read remainder briefly
        end=time.time()+0.1
        while time.time()<end:
            r,_,_=select.select([master],[],[],0.01)
            if not r: continue
            try:
                chunk=os.read(master,8192)
                if not chunk: break
                data += chunk
            except OSError: break
        break
rc=p.poll()
if rc is None:
    p.terminate()
    try: p.wait(timeout=0.5)
    except subprocess.TimeoutExpired:
        p.kill(); p.wait()
    rc=p.returncode
print('RC', rc)
print('BYTES', len(data))
sys.stdout.buffer.write(data)
PY
